import{_ as h,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Retrieval Practice","description":"","frontmatter":{},"headers":[],"relativePath":"learning/retrieval-practice.md","filePath":"learning/retrieval-practice.md"}'),c={name:"learning/retrieval-practice.md"};function o(r,n,e,g,l,u){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="retrieval-practice" tabindex="-1">Retrieval Practice <a class="header-anchor" href="#retrieval-practice" aria-label="Permalink to &quot;Retrieval Practice&quot;">​</a></h1><p>Trên trang này# Retrieval Practice — nhớ lại chủ động <a href="#retrieval-practice-—-nho-lai-chu-đong">​</a> Việc học xảy ra khi learner <strong>lấy kiến thức ra khỏi đầu</strong>, chứ không phải khi kiến thức đi vào. Đây là kết quả được kiểm chứng nhiều lần nhất trong toàn bộ khoa học học tập, và cũng là kết quả bị làm ngược nhiều nhất trong thực tế.</p><h2 id="thi-nghiem-can-biet-​" tabindex="-1">Thí nghiệm cần biết <a href="#thi-nghiem-can-biet">​</a> <a class="header-anchor" href="#thi-nghiem-can-biet-​" aria-label="Permalink to &quot;Thí nghiệm cần biết [​](#thi-nghiem-can-biet)&quot;">​</a></h2><p>Cho hai nhóm học cùng một tài liệu. Nhóm A đọc lại bốn lần. Nhóm B đọc một lần rồi ba lần tự nhớ lại xem tài liệu nói gì mà không nhìn sách. Hỏi ngay sau đó: nhóm A tự tin hơn hẳn và làm bài tốt hơn một chút. Hỏi lại sau một tuần: <strong>nhóm B vượt xa</strong> — thường là rất xa. Hai phần của kết quả này đều quan trọng. Nhóm B nhớ tốt hơn <em>và</em> nhóm A tự tin hơn. Nghĩa là cách học kém hiệu quả lại tạo ra cảm giác chắc chắn cao hơn. Đây là lý do hiểu lầm này khó sửa: trải nghiệm chủ quan nói ngược lại sự thật.</p><h2 id="vi-sao-lay-ra-lai-manh-hon-nap-vao-​" tabindex="-1">Vì sao lấy ra lại mạnh hơn nạp vào <a href="#vi-sao-lay-ra-lai-manh-hon-nap-vao">​</a> <a class="header-anchor" href="#vi-sao-lay-ra-lai-manh-hon-nap-vao-​" aria-label="Permalink to &quot;Vì sao lấy ra lại mạnh hơn nạp vào [​](#vi-sao-lay-ra-lai-manh-hon-nap-vao)&quot;">​</a></h2><p>Mỗi lần nhớ lại thành công, con đường dẫn tới ký ức đó được củng cố. Chỉ đọc lại thì con đường không được dùng — nội dung được nhận diện là <em>quen</em>, và bộ não nhầm cảm giác quen thuộc đó với hiểu biết. Còn một tác dụng ít được nói tới: nhớ lại <strong>phơi bày chỗ hổng ngay lập tức</strong>. Đọc lại thì mọi thứ trông đều ổn. Cố viết ra thì lập tức lộ ra hai chỗ nói không nổi — và đúng hai chỗ đó là nơi đáng dành thời gian.</p><h2 id="nemo12-xay-đieu-nay-vao-đau-​" tabindex="-1">Nemo12 xây điều này vào đâu <a href="#nemo12-xay-đieu-nay-vao-đau">​</a> <a class="header-anchor" href="#nemo12-xay-đieu-nay-vao-đau-​" aria-label="Permalink to &quot;Nemo12 xây điều này vào đâu [​](#nemo12-xay-đieu-nay-vao-đau)&quot;">​</a></h2><p>Gần như mọi chỗ. Nhưng có vài chi tiết đáng chú ý: <strong>Retrieval trước, giải thích sau.</strong> Khi con vào một buổi ôn nhanh, hệ thống hỏi trước, giải thích sau — kể cả khi biết trước con có thể sai. Thử nhớ và trượt vẫn tạo ra việc học tốt hơn là được nhắc trước rồi mới hỏi. <strong>Buổi ôn rất ngắn.</strong> Hai câu, tám phút. Không phải &quot;ôn lại chương 3&quot;. Retrieval hiệu quả với liều nhỏ và thường xuyên, không cần buổi ôn dài. <strong>Đo cả cách nhớ lại.</strong> Sau khi chọn đáp án, con được hỏi đã làm thế nào: tự suy ra, nhớ lại, loại trừ, hay đoán. Nếu con tự khai là đoán, hệ thống <strong>không tính đó là một lần nhớ lại thành công</strong> dù đáp án đúng. Trí nhớ không được bồi bằng may mắn. <strong>Nhớ lại xen kẽ có giá trị hơn.</strong> Nhớ lại A khi vừa làm xong một loạt bài A thì dễ — nội dung còn đang nằm sẵn trong đầu. Nhớ lại A sau khi đã đi qua B và C mới là bằng chứng thật. Hệ thống xếp bài xen kẽ chính vì lý do đó, và tính bằng chứng loại này ở mức cao hơn.</p><h2 id="cach-mot-gia-đinh-dung-đuoc-ngay-​" tabindex="-1">Cách một gia đình dùng được ngay <a href="#cach-mot-gia-đinh-dung-đuoc-ngay">​</a> <a class="header-anchor" href="#cach-mot-gia-đinh-dung-đuoc-ngay-​" aria-label="Permalink to &quot;Cách một gia đình dùng được ngay [​](#cach-mot-gia-đinh-dung-đuoc-ngay)&quot;">​</a></h2><p>Đổi câu hỏi ở nhà. Thay vì <em>&quot;Con học bài chưa?&quot;</em> — vốn chỉ đo thời gian ngồi bàn — hãy hỏi:</p><ul><li>&quot;Hôm nay con học gì? Kể lại cho mẹ nghe, đừng mở vở.&quot;</li><li>&quot;Chỗ này con giải thích cho mẹ hiểu được không?&quot;</li><li>&quot;Tuần trước con học phần nào? Còn nhớ không?&quot; Ba câu này chính là retrieval practice, và chúng miễn phí. Chúng cũng có tác dụng phụ đáng giá: bạn nghe được con <strong>hiểu tới đâu</strong>, thay vì chỉ nhìn thấy vở đã ghi kín. Nếu con không nhớ được thì sao? Đó là thông tin, không phải thất bại. Nó chỉ ra chính xác chỗ cần quay lại — điều mà một buổi đọc lại êm ả sẽ không bao giờ cho bạn biết. Phản ứng đúng là &quot;à, chỗ này mờ rồi, mình xem lại nhé&quot;, không phải &quot;sao học rồi mà quên?&quot;.</li></ul><h2 id="vi-sao-no-co-cam-giac-kho-chiu-​" tabindex="-1">Vì sao nó có cảm giác khó chịu <a href="#vi-sao-no-co-cam-giac-kho-chiu">​</a> <a class="header-anchor" href="#vi-sao-no-co-cam-giac-kho-chiu-​" aria-label="Permalink to &quot;Vì sao nó có cảm giác khó chịu [​](#vi-sao-no-co-cam-giac-kho-chiu)&quot;">​</a></h2><p>Retrieval practice khó hơn đọc lại, và learner thường thấy mình đang học <strong>kém đi</strong> khi mới chuyển sang cách này. Cảm giác đó sai nhưng rất mạnh, nên đáng nói trước với con: <em>phần khó chính là phần có tác dụng</em>. Nếu buổi học nào cũng trôi chảy dễ chịu, nhiều khả năng nó không tạo ra thay đổi nào. <a href="/learning/worked-examples">Worked Examples — bài mẫu giải sẵn →</a></p>',13)])])}const v=h(c,[["render",o]]);export{s as __pageData,v as default};
